import java.util.*;

public class Ex05 {
    static class Bean { Bean() { System.out.println("[bean] constructed"); } }
    static class BeanFactory {
        private final Map<String, Bean> cache = new HashMap<>();
        Bean get() { return cache.computeIfAbsent("b", k -> new Bean()); } // 懒加载
    }
    static class AppContext {
        final Bean b; // 构造即创建（预实例化/饿汉）
        AppContext() { this.b = new Bean(); }
        Bean get() { return b; }
    }
    public static void main(String[] args) {
        System.out.println("-- BeanFactory (lazy) --");
        BeanFactory bf = new BeanFactory();
        System.out.println("factory created, bean not yet built");
        bf.get(); // 此刻才构造
        bf.get(); // 命中缓存，不再构造
        System.out.println("-- ApplicationContext (eager) --");
        AppContext ctx = new AppContext(); // 构造时即创建
        ctx.get();
    }
}
